prelude_js:
// 本片数字由 scratchpad 独立核算过，逐条列在这里（对照 05_cs224r_offpolicy_actor_critic_2025.pdf）
//   ε = 0.2 ⇒ 截断区间 [0.8, 1.2]（p13 原文 clipping range ϵ =0.2）
//   Â=+1：w≤1.2 随线，w>1.2 **变平**（min 取 1.2·Â）；w<0.8 **不平**，继续随线
//   Â=-1：w<0.8 **变平**（min 取 0.8·Â）；w>1.2 **不平**，继续随线（这正是 min 的功劳）
//   ⇒ 平的那一段永远在「会让目标变大」的那一侧。这是本片的 aha。
//   讲稿例子：Â=-1000, π_new=0.9, π_old=0.1 ⇒ w=9；未截 -9000，截到 1.2 得 -1200，
//     -1200 > -9000 看起来更好 ⇒ min(-9000,-1200) = -9000，截断在此不生效
//   p13 超参：一批 ~2000 步 · ~10 epoch · batch 64 ⇒ ~300 次梯度步 · ~500 轮 ⇒ ~1M 步

/* ══ 本片共用同一张图：代理目标 J̃ 关于比值 w 的分段函数 ══
   坐标写死并复用，是为了让五个知识点看到的是「同一张图在长」，
   而不是五张互不相干的示意图。KP3-KP5 全部在这张图上演化。 */
var PX0=360, PX1=940;           /* w = 0 .. 2 对应的横向像素 */
var PYM=258, VSC=64;            /* v = 0 的高度；每一个单位 v 占的像素 */
var EPS=0.2, WLO=0.8, WHI=1.2;

function wx(w){ return PX0 + (PX1-PX0)*(w/2); }
function vy(v){ return PYM - VSC*v; }
function clipw(w){ return Math.max(WLO, Math.min(WHI, w)); }

/* 三条线的采样点。A 是优势的符号（本片只用 +1 / -1） */
function ptsRaw(A){ var p=[],w; for(w=0;w<=2.0001;w+=0.05) p.push([wx(w),vy(w*A)]); return p; }
function ptsClip(A){ var p=[],w; for(w=0;w<=2.0001;w+=0.05) p.push([wx(w),vy(clipw(w)*A)]); return p; }
function ptsMin(A){ var p=[],w,v; for(w=0;w<=2.0001;w+=0.05){ v=Math.min(w*A, clipw(w)*A); p.push([wx(w),vy(v)]); } return p; }

/* 画坐标框：横轴是 w，零线在 PYM，两条竖线标 1±ε */
function frame(){
  E.gS.append("line").attr("class","axline").attr("x1",PX0-14).attr("x2",PX1+14)
     .attr("y1",PYM).attr("y2",PYM);
  E.gS.append("line").attr("class","axline").attr("x1",wx(1)).attr("x2",wx(1))
     .attr("y1",vy(2.1)).attr("y2",vy(-2.1));
}
/* 截断区间的两条竖虚线 */
function band(){
  [WLO,WHI].forEach(function(w){
    E.gS.append("line").attr("class","tedge sm").attr("stroke-dasharray","4 4")
       .attr("x1",wx(w)).attr("x2",wx(w)).attr("y1",vy(2.1)).attr("y2",vy(-2.1));
  });
}

